def find_judge(n, trust):
    indeg = [0] * n
    outdeg = [0] * n
    for a, b in trust:
        outdeg[a] += 1
        indeg[b] += 1
    for p in range(n):
        if indeg[p] == n - 1 and outdeg[p] == 0:
            return p
    return -1

def tree_centers(n, edges):
    adj = [[] for _ in range(n)]
    degree = [0] * n
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
        degree[u] += 1
        degree[v] += 1
    leaves = deque(i for i in range(n) if degree[i] == 1)
    remaining = n
    while remaining > 2:
        for _ in range(len(leaves)):
            leaf = leaves.popleft()
            remaining -= 1
            for nb in adj[leaf]:
                degree[nb] -= 1
                if degree[nb] == 1:
                    leaves.append(nb)
    return list(leaves)

